def connect_dots(grid, dot, line, bg=None):
    """Fill line color strictly between every pair of dots sharing a row or column."""
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    pts = [(i, j) for i in range(h) for j in range(w) if grid[i][j] == dot]
    rows = {}
    cols = {}
    for i, j in pts:
        rows.setdefault(i, []).append(j)
        cols.setdefault(j, []).append(i)
    for i, js in rows.items():
        if len(js) > 1:
            for j in range(min(js), max(js) + 1):
                if g[i][j] != dot: g[i][j] = line
    for j, is_ in cols.items():
        if len(is_) > 1:
            for i in range(min(is_), max(is_) + 1):
                if g[i][j] != dot: g[i][j] = line
    return g

